#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;

ll power(ll b, ll e) { ll r = 1; b %= MOD; for (; e; e >>= 1, b = b * b % MOD) if (e & 1) r = r * b % MOD; return r; }

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    vector<int> p(n);
    for (auto &x : p) { scanf("%d", &x); x--; }
    // Smallest prime factor sieve up to n.
    vector<int> spf(n + 1);
    iota(spf.begin(), spf.end(), 0);
    for (ll i = 2; i * i <= n; i++)
        if (spf[i] == i)
            for (ll j = i * i; j <= n; j += i)
                if (spf[j] == j) spf[j] = i;
    // Answer = lcm of cycle lengths, kept as the max exponent of each prime.
    vector<int> maxPow(n + 1, 0);
    vector<char> seen(n, 0);
    for (int i = 0; i < n; i++) {
        if (seen[i]) continue;
        int len = 0;
        for (int u = i; !seen[u]; u = p[u]) { seen[u] = 1; len++; }
        for (int x = len; x > 1;) {
            int pr = spf[x], e = 0;
            while (x % pr == 0) { x /= pr; e++; }
            maxPow[pr] = max(maxPow[pr], e);
        }
    }
    ll ans = 1;
    for (int pr = 2; pr <= n; pr++)
        if (maxPow[pr]) ans = ans * power(pr, maxPow[pr]) % MOD;
    printf("%lld\n", ans);
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static long power(long b, long e) {
        long r = 1;
        b %= MOD;
        for (; e > 0; e >>= 1, b = b * b % MOD) if ((e & 1) == 1) r = r * b % MOD;
        return r;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.nextToken();
        int n = (int) st.nval;
        int[] p = new int[n];
        for (int i = 0; i < n; i++) { st.nextToken(); p[i] = (int) st.nval - 1; }
        // Smallest prime factor sieve up to n.
        int[] spf = new int[n + 1];
        for (int i = 0; i <= n; i++) spf[i] = i;
        for (long i = 2; i * i <= n; i++)
            if (spf[(int) i] == i)
                for (long j = i * i; j <= n; j += i)
                    if (spf[(int) j] == j) spf[(int) j] = (int) i;
        // Answer = lcm of cycle lengths, kept as the max exponent of each prime.
        int[] maxPow = new int[n + 1];
        boolean[] seen = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            int len = 0;
            for (int u = i; !seen[u]; u = p[u]) { seen[u] = true; len++; }
            for (int x = len; x > 1;) {
                int pr = spf[x], e = 0;
                while (x % pr == 0) { x /= pr; e++; }
                maxPow[pr] = Math.max(maxPow[pr], e);
            }
        }
        long ans = 1;
        for (int pr = 2; pr <= n; pr++)
            if (maxPow[pr] > 0) ans = ans * power(pr, maxPow[pr]) % MOD;
        System.out.println(ans);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1_000_000_007

func power(b, e int64) int64 {
	r := int64(1)
	b %= MOD
	for ; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * b % MOD
		}
		b = b * b % MOD
	}
	return r
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	p := make([]int, n)
	for i := range p {
		fmt.Fscan(in, &p[i])
		p[i]--
	}
	// Smallest prime factor sieve up to n.
	spf := make([]int, n+1)
	for i := range spf {
		spf[i] = i
	}
	for i := 2; i*i <= n; i++ {
		if spf[i] == i {
			for j := i * i; j <= n; j += i {
				if spf[j] == j {
					spf[j] = i
				}
			}
		}
	}
	// Answer = lcm of cycle lengths, kept as the max exponent of each prime.
	maxPow := make([]int64, n+1)
	seen := make([]bool, n)
	for i := 0; i < n; i++ {
		if seen[i] {
			continue
		}
		length := 0
		for u := i; !seen[u]; u = p[u] {
			seen[u] = true
			length++
		}
		for x := length; x > 1; {
			pr, e := spf[x], int64(0)
			for x%pr == 0 {
				x /= pr
				e++
			}
			maxPow[pr] = max(maxPow[pr], e)
		}
	}
	ans := int64(1)
	for pr := 2; pr <= n; pr++ {
		if maxPow[pr] > 0 {
			ans = ans * power(int64(pr), maxPow[pr]) % MOD
		}
	}
	fmt.Println(ans)
}
